// tests/audio/test_audio_stft.cpp
//
// Parity and contract tests for the shared FFT / linear STFT frontend:
//   * audio_fft_radix2 vs a naive DFT reference,
//   * audio_stft_magnitude vs tests/audio/ref/stft_magnitude.npy
//     (numpy reference generated by tests/audio/generate_reference.py; the
//     script also stores the exact input samples so the two cannot drift),
//   * invalid-argument and short-input edge cases.

#include <gtest/gtest.h>

#include "gpt_sovits/audio.h"

#include "cnpy.h"

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <random>
#include <string>
#include <vector>

namespace {

const std::string kRefDir = std::string(AUDIO_TEST_DIR) + "ref/";

static bool file_exists(const std::string & p) {
    FILE * f = fopen(p.c_str(), "rb");
    if (!f) return false;
    fclose(f);
    return true;
}

static std::vector<float> load_f32(const std::string & path, std::vector<size_t> * shape = nullptr) {
    cnpy::NpyArray arr = cnpy::npy_load(path);
    if (shape) *shape = arr.shape;
    if (arr.word_size != 4) {
        ADD_FAILURE() << "expected float32 npy: " << path;
        return {};
    }
    const float * p = arr.data<float>();
    return std::vector<float>(p, p + arr.num_vals);
}

// Naive O(n^2) DFT used only to validate the radix-2 implementation.
static void naive_dft(const std::vector<float> & in, std::vector<double> & re, std::vector<double> & im) {
    const size_t n = in.size();
    re.assign(n, 0.0);
    im.assign(n, 0.0);
    const double pi = 3.14159265358979323846;
    for (size_t k = 0; k < n; ++k) {
        double sr = 0.0, si = 0.0;
        for (size_t t = 0; t < n; ++t) {
            // e^{-i 2 pi k t / n} = cos - i sin
            const double ang = -2.0 * pi * static_cast<double>(k * t) / static_cast<double>(n);
            sr += in[t] * std::cos(ang);
            si += in[t] * std::sin(ang);
        }
        re[k] = sr;
        im[k] = si;
    }
}

TEST(AudioFFT, RejectsInvalidSizes) {
    float re[8] = {};
    float im[8] = {};
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(nullptr, im, 8));
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(re, nullptr, 8));
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(re, im, 0));
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(re, im, -1));
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(re, im, 3));
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(re, im, 6));
    EXPECT_FALSE(gpt_sovits::audio_fft_radix2(re, im, 12));
}

TEST(AudioFFT, SizeOneIsIdentity) {
    float re[1] = {2.5f};
    float im[1] = {-1.25f};
    ASSERT_TRUE(gpt_sovits::audio_fft_radix2(re, im, 1));
    EXPECT_FLOAT_EQ(re[0], 2.5f);
    EXPECT_FLOAT_EQ(im[0], -1.25f);
}

TEST(AudioFFT, MatchesNaiveDft) {
    constexpr int n = 64;
    std::vector<float> in(n);
    for (int i = 0; i < n; ++i) {
        in[i] = static_cast<float>(std::sin(0.17 * i) + 0.3 * std::cos(0.41 * i + 0.2));
    }

    std::vector<double> er, ei;
    naive_dft(in, er, ei);

    std::vector<float> re(in), im(n, 0.0f);
    ASSERT_TRUE(gpt_sovits::audio_fft_radix2(re.data(), im.data(), n));

    double max_abs = 0.0;
    for (int k = 0; k < n; ++k) {
        max_abs = std::max(max_abs, std::fabs(static_cast<double>(re[k]) - er[k]));
        max_abs = std::max(max_abs, std::fabs(static_cast<double>(im[k]) - ei[k]));
    }
    EXPECT_LT(max_abs, 1e-4) << "radix-2 FFT differs from naive DFT";
}

// Main parity check: the numpy fixture was produced with the same signal and
// the same upstream hyperparameters (32 kHz, n_fft=2048, hop=640, win=2048).
TEST(AudioSTFT, MatchesNumpyReference) {
    const std::string in_path  = kRefDir + "stft_input.npy";
    const std::string ref_path = kRefDir + "stft_magnitude.npy";
    if (!file_exists(in_path) || !file_exists(ref_path)) {
        GTEST_SKIP() << "audio reference fixtures missing under " << kRefDir;
    }

    std::vector<size_t> in_shape, ref_shape;
    const std::vector<float> input = load_f32(in_path, &in_shape);
    const std::vector<float> ref   = load_f32(ref_path, &ref_shape);
    ASSERT_FALSE(input.empty());
    ASSERT_EQ(ref_shape.size(), 2u) << "expected [n_frames, n_bins] reference";

    const int64_t n_frames_ref = static_cast<int64_t>(ref_shape[0]);
    const int64_t n_bins_ref   = static_cast<int64_t>(ref_shape[1]);
    ASSERT_EQ(static_cast<size_t>(n_frames_ref * n_bins_ref), ref.size());

    std::vector<float> out;
    int64_t frames = -1;
    ASSERT_TRUE(gpt_sovits::audio_stft_magnitude(
        input.data(), static_cast<int64_t>(input.size()),
        2048, 640, 2048, out, &frames));
    ASSERT_EQ(frames, n_frames_ref);
    ASSERT_EQ(out.size(), ref.size());

    double max_abs = 0.0, max_ref = 0.0, ss = 0.0;
    for (size_t i = 0; i < ref.size(); ++i) {
        const double a = out[i];
        const double b = ref[i];
        ASSERT_TRUE(std::isfinite(a));
        max_abs = std::max(max_abs, std::fabs(a - b));
        max_ref = std::max(max_ref, std::fabs(b));
        ss += (a - b) * (a - b);
    }
    const double rel = (max_ref > 0.0) ? max_abs / max_ref : max_abs;
    const double rmse = std::sqrt(ss / ref.size());
    printf("[stft] frames=%lld bins=%lld max_abs=%.3e rel=%.3e rmse=%.3e\n",
           static_cast<long long>(frames), static_cast<long long>(n_bins_ref),
           max_abs, rel, rmse);
    EXPECT_LT(rel, 1e-4) << "STFT differs from the numpy reference";
}

// A C++-generated deterministic signal (sum of bin-centred sines + mt19937
// noise) exercises the frontend without the npy fixture and checks that the
// strongest component lands in the expected bin.
TEST(AudioSTFT, PeakBinFromGeneratedSignal) {
    constexpr int n_fft = 2048;
    constexpr int n     = 2 * n_fft;
    constexpr int k0    = 100;   // bin-centred tone
    std::mt19937 rng(12345u);
    std::uniform_real_distribution<float> noise(-0.01f, 0.01f);

    std::vector<float> x(n);
    for (int i = 0; i < n; ++i) {
        const double tone = 0.7 * std::sin(2.0 * 3.14159265358979323846 * k0 * i / n_fft);
        x[i] = static_cast<float>(tone) + 0.15f * std::sin(2.0f * 3.14159265f * 400.0f * i / n_fft) + noise(rng);
    }

    std::vector<float> out;
    int64_t frames = 0;
    // hop == n_fft -> no reflect padding and no overlap.
    ASSERT_TRUE(gpt_sovits::audio_stft_magnitude(x.data(), n, n_fft, n_fft, n_fft, out, &frames));
    ASSERT_EQ(frames, 2);
    ASSERT_EQ(out.size(), static_cast<size_t>(frames) * (n_fft / 2 + 1));

    size_t peak = 0;
    for (int k = 0; k <= n_fft / 2; ++k) {
        if (out[static_cast<size_t>(k)] > out[peak]) peak = static_cast<size_t>(k);
    }
    EXPECT_EQ(peak, static_cast<size_t>(k0));
}

TEST(AudioSTFT, ShortInputProducesOneFrame) {
    // 1000 < win_length=2048, but reflect pad (704) is still < 1000.
    std::vector<float> x(1000, 0.1f);
    std::vector<float> out;
    int64_t frames = -1;
    ASSERT_TRUE(gpt_sovits::audio_stft_magnitude(x.data(), 1000, 2048, 640, 2048, out, &frames));
    EXPECT_EQ(frames, 1);
    EXPECT_EQ(out.size(), static_cast<size_t>(2048 / 2 + 1));
    for (float v : out) EXPECT_TRUE(std::isfinite(v));
}

// torch.stft centers a short window inside the n_fft frame ("pad center"):
// the left pad is floor((n_fft - win_length) / 2). This case uses an odd
// window length so a left-aligned or right-rounded window would be detected.
TEST(AudioSTFT, CentersShortWindow) {
    constexpr int    n_fft = 64;
    constexpr int    hop   = 16;
    constexpr int    win   = 31;
    constexpr int    n     = 128;
    constexpr double kPiD  = 3.14159265358979323846;

    std::vector<float> x(n);
    for (int i = 0; i < n; ++i) {
        x[i] = static_cast<float>(
            0.7 * std::sin(2.0 * kPiD * 3.0 * i / n_fft)
          + 0.4 * std::cos(2.0 * kPiD * 7.0 * i / n_fft + 0.3)
          + 0.1 * std::sin(2.0 * kPiD * 11.0 * i / n_fft));
    }

    std::vector<float> out;
    int64_t frames = 0;
    ASSERT_TRUE(gpt_sovits::audio_stft_magnitude(
        x.data(), n, n_fft, hop, win, out, &frames));

    const int pad           = (n_fft - hop) / 2;
    const int n_padded      = n + 2 * pad;
    const int expect_frames = 1 + (n_padded - n_fft) / hop;
    ASSERT_EQ(frames, expect_frames);
    EXPECT_EQ(out.size(), static_cast<size_t>(expect_frames) * (n_fft / 2 + 1));

    std::vector<double> win_vals(win);
    for (int i = 0; i < win; ++i) {
        win_vals[i] = 0.5 - 0.5 * std::cos(2.0 * kPiD * i / win);
    }
    // (n_fft - win) / 2 with win=31, n_fft=64 -> floor(33/2) = 16.
    constexpr int win_offset = 16;

    std::vector<float> padded(n_padded);
    for (int i = 0; i < n_padded; ++i) {
        int s = i - pad;
        if (s < 0) {
            s = -s;
        } else if (s >= n) {
            s = 2 * (n - 1) - s;
        }
        padded[i] = x[s];
    }

    const int n_bins = n_fft / 2 + 1;
    for (int64_t t = 0; t < frames; ++t) {
        std::vector<float> frame(n_fft, 0.0f);
        for (int i = 0; i < n_fft; ++i) {
            const int wi = i - win_offset;
            if (wi >= 0 && wi < win) {
                frame[i] = static_cast<float>(
                    padded[static_cast<size_t>(t * hop + i)] * win_vals[wi]);
            }
        }

        std::vector<double> re, im;
        naive_dft(frame, re, im);
        for (int k = 0; k < n_bins; ++k) {
            const double expected = std::sqrt(re[k] * re[k] + im[k] * im[k] + 1e-6);
            EXPECT_NEAR(out[static_cast<size_t>(t) * n_bins + k], expected, 1e-4)
                << "frame " << t << " bin " << k;
        }
    }
}

TEST(AudioSTFT, RejectsInvalidArguments) {
    std::vector<float> x(4096, 0.1f);
    std::vector<float> out;
    int64_t frames = 99;

    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(nullptr, 4096, 2048, 640, 2048, out, &frames));
    EXPECT_EQ(frames, 0);
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 0, 2048, 640, 2048, out));
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 4096, 1000, 640, 1000, out));
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 4096, 2048, 0, 2048, out));
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 4096, 2048, -640, 2048, out));
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 4096, 2048, 640, 0, out));
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 4096, 2048, 640, 4096, out));
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 4096, 512, 640, 512, out));
    // Reflect pad (2048-640)/2 = 704 is not < n_samples.
    EXPECT_FALSE(gpt_sovits::audio_stft_magnitude(x.data(), 704, 2048, 640, 2048, out));

    // Failed calls must not report frames.
    EXPECT_EQ(frames, 0);
}

} // namespace
